__NUXT_JSONP__("/finanzas-publicas/publicaciones/paquete_economico_2025_el_inicio_de_una_nueva_gestion", (function(a,b,c,d,e,f,g,h,i,j,k){return {data:[{post:{slug:"paquete_economico_2025_el_inicio_de_una_nueva_gestion",title:"Paquete Económico 2025: el inicio de una nueva gestión",date:"2024-12-04T17:01:04.723Z",img:"https:\u002F\u002Fucarecdn.com\u002Fa96333a9-0fda-49ca-822b-14a0e214796f\u002F","img-alt":"Paquete económico 2025",autor:"Dalia Toledo y Mireya Mondragón",category:b,extracto:"Sin una reforma fiscal que nos permita aumentar de forma significativa nuestros ingresos, el gran perdedor del Paquete Económico 2025 serán las y los mexicanos, pues el gasto público fue recortado en rubros que son altamente sensibles, como la salud o la inversión pública, por ejemplo.",file:"https:\u002F\u002Fucarecdn.com\u002Fba3f7479-a408-4c13-99d5-e606c983d2c0\u002F",toc:[],body:{type:c,children:[{type:d,tag:e,props:{},children:[{type:a,value:"Sin una reforma fiscal que nos permita aumentar de forma significativa nuestros ingresos, el gran perdedor del Paquete Económico 2025 serán las y los mexicanos, pues el gasto público fue recortado en rubros que son altamente sensibles, como la salud o la inversión pública, por ejemplo."}]}]},dir:f,path:"\u002Fpublicaciones\u002Fpaquete_economico_2025_el_inicio_de_una_nueva_gestion",extension:g,createdAt:"2025-04-23T06:21:15.399Z",updatedAt:"2025-04-23T06:21:15.400Z"},publicaciones:[{slug:"acelerando_la_fiscalidad_efectiva_al_tabaco_en_america_latina-_el_caso_de_mexico",title:"ACELERANDO LA FISCALIDAD EFECTIVA AL TABACO EN AMÉRICA LATINA. EL CASO DE MÉXICO",date:"2019-08-25T13:58:35.842Z",img:"https:\u002F\u002Fucarecdn.com\u002F4ecef13f-133d-46c0-879c-f8bd65f1eeda\u002F","img-alt":"Portada impuestos al tabaco",autor:"Liliana Alvarado, Dalia Toledo, Rodrigo Bolaños, Alejandro Alegría Matus, Claudia Cordova",category:b,extracto:i,file:"https:\u002F\u002Fucarecdn.com\u002Fd0a1a550-a3b4-4f74-a9ca-038c4ac33431\u002F",toc:[],body:{type:c,children:[{type:a,value:h},{type:d,tag:e,props:{},children:[{type:a,value:i}]},{type:a,value:h}]},dir:f,path:"\u002Fpublicaciones\u002Facelerando_la_fiscalidad_efectiva_al_tabaco_en_america_latina-_el_caso_de_mexico",extension:g,createdAt:"2023-06-19T05:12:04.224Z",updatedAt:"2022-08-28T22:41:58.244Z"},{slug:"analisis_del_paquete_economico_2026",title:"Análisis del Paquete Económico 2026",date:"2025-09-26T18:38:47.603Z",img:"https:\u002F\u002Fucarecdn.com\u002F89215cd3-b725-4493-8415-8a4c213d7dcc\u002F","img-alt":"Paquete económico 2026",autor:"Liliana Alvarado, Dalia Toledo y Mireya Mondragón",category:b,extracto:"El Paquete Económico 2026 es uno de los pilares sobre los cuales la presidenta Sheinbaum cimentará su proyecto de nación, y sin una reforma fiscal que permita aumentar los ingresos significativamente, ¿cuáles son las variables que se esperan que cambien para poder atender las necesidades de inversión, para garantizar bienes y servicios de calidad y hacer frente a los problemas que frenan el crecimiento económico y que impactan en el bienestar de la sociedad mexicana?",file:"https:\u002F\u002Fucarecdn.com\u002F977e0e4c-d871-496e-bcfe-b6917138e21e\u002F",toc:[],body:{type:c,children:[{type:d,tag:e,props:{},children:[{type:a,value:"En términos presupuestales, el primer año de la administración de la presidenta Claudia Sheinbum ha estado marcado por importantes recortes al gasto público y, aunque hay un fuerte interés por sanear las finanzas, las metas de endeudamiento no se están alcanzando. En ese sentido, este paquete es el segundo de los pilares sobre los cuales la presidenta Sheinbaum cimentará su proyecto de nación, y sin una reforma fiscal que permita aumentar los ingresos significativamente, ¿cuáles son las variables que se esperan que cambien para poder atender las necesidades de inversión, para garantizar bienes y servicios de calidad y hacer frente a los problemas que frenan el crecimiento económico y que impactan en el bienestar de la sociedad mexicana? Este documento intenta dar luz sobre estas preguntas."}]}]},dir:f,path:"\u002Fpublicaciones\u002Fanalisis_del_paquete_economico_2026",extension:g,createdAt:j,updatedAt:j},{slug:"analisis_del_paquete_fiscal_2010",title:"ANÁLISIS DEL PAQUETE FISCAL 2010",date:"2009-11-09T21:35:34.285Z",img:"https:\u002F\u002Fucarecdn.com\u002F3a044046-e93e-49f4-9df2-c1fc290cb776\u002F",autor:"Liliana Alvarado, Carlos Gaitán Lastras.",category:b,extracto:k,file:"https:\u002F\u002Fucarecdn.com\u002Fb0d5392f-78da-4c7c-a8a1-02b6b9e6bf91\u002F",toc:[],body:{type:c,children:[{type:a,value:h},{type:d,tag:e,props:{},children:[{type:a,value:k}]},{type:a,value:h}]},dir:f,path:"\u002Fpublicaciones\u002Fanalisis_del_paquete_fiscal_2010",extension:g,createdAt:"2023-06-19T05:12:04.231Z",updatedAt:"2022-08-24T22:31:42.859Z"}]}],fetch:{},mutations:[]}}("text","finanzas-publicas","root","element","p","\u002Fpublicaciones",".md","\n","Este estudio analiza las políticas de control del tabaco que se han implementado en México, enfocándose, en particular, en la efectividad que ha tenido la política tributaria para reducir el consumo de cigarrillos y en el impacto que el tabaquismo ha tenido sobre las finanzas públicas.","2025-11-25T01:24:03.286Z","Desafortunadamente, las modificaciones en materia fiscal no son de largo plazo, atienden sólo a las coyunturas económicas y políticas del momento")));